mapper.select:
SELECT COUNT(1) FROM t_test t JOIN t_category c ON c.id = t.category_id AND c.deleted = 0 WHERE t.deleted = 0 AND NOT EXISTS ( SELECT 1 FROM t_ai_generation_task ai_task JOIN t_test_version ai_version ON ai_version.id = ai_task.version_id WHERE ai_version.test_id = t.id AND ai_task.deleted = 0 AND ai_task.task_status != 5 )
AND t.test_name LIKE CONCAT('%', #{query.keyword}, '%')
AND t.test_type = #{query.testType} AND t.category_id = #{query.categoryId} AND t.status = #{query.status}
